insert into public.sports_teams (external_key, name, short_name, sport, league, country, city, stadium, stadium_capacity, stadium_capacity_source_url, founded_year, domain, ownership_type, ownership_summary, ownership_source_url, revenue, revenue_currency, revenue_season, revenue_source_name, revenue_source_url, valuation, valuation_currency, valuation_year, valuation_source_name, valuation_source_url, social_followers, social_as_of, social_source_url, social_platforms, notes, sources, verification, source)
  values ('premier-league--brentford', 'Brentford Football Club', 'Brentford', 'football', 'Premier League', 'England', 'London', 'Gtech Community Stadium', 17250, 'https://www.football-stadiums.co.uk/grounds/brentford-community-stadium/', 1889, 'brentfordfc.com', 'individual_family', 'Matthew Benham, who took full control in 2012, remains majority shareholder through holding company Best Intentions Analytics Limited (BIA), formed in February 2025 to hold his shares in Brentford FC and Spanish club Merida AD. Minority shareholders are Gary Lubner (via This Day Sports and Media Ltd) and Sir Matthew Vaughn (via MARV Bee Ltd) since July 2025, joined in March 2026 by Blackstone executive Prakash Melwani and Universal Music Group CEO Sir Lucian Grainge; stake sizes have not been disclosed by the club.', 'https://www.brentfordfc.com/en/news/club-news-brentford-announces-further-investment-prakash-melwani-sir-lucian-grainge-cbe', 173100000, 'GBP', '2024-25', 'Brentford FC (financial results for 2024/25 season)', 'https://www.brentfordfc.com/en/news/article/club-news-brentford-fc-financial-results-2024-25', 400000000, 'GBP', 2025, 'SportsPro (valuation implied by July 2025 minority stake sale)', 'https://www.sportspro.com/news/brentford-investment-gary-lubner-matthew-vaughn-benham-july-2025/', null, '2026-09-28', 'https://www.instagram.com/brentfordfc/', '[{"platform": "Instagram", "followers": 889000, "as_of": "2026-09-28", "source_url": "https://www.instagram.com/brentfordfc/"}, {"platform": "Facebook", "followers": 1800000, "as_of": "2026-09-28", "source_url": "https://www.facebook.com/brentfordfootballclub1889/"}, {"platform": "X", "followers": 228600, "as_of": "2026-09-28", "source_url": "https://www.speakrj.com/audit/report/BrentfordFC/twitter"}]'::jsonb, 'Stake sizes: the club has never disclosed the minority holdings. Non-authoritative sites (brandsownedby.com, whoistheownerof.com) state Benham 90%, Lubner 5%, Vaughn 5% as of late 2025, before the March 2026 round in which Lubner and Vaughn increased holdings and Melwani and Grainge entered; treat those percentages as unverified. SportsPro reported up to 25% could ultimately change hands. Valuation: the £400m figure is the valuation implied by the July 2025 minority sale (SportsPro; City AM), not a Forbes/Sportico estimate. Sportico''s 2026 list references the Brentford LP deal at about $540m and notes LP deals price below control valuations; Brentford does not appear in Forbes'' 2026 top 30. Deloitte Football Money League 2026 lists Brentford 30th with EUR 206m revenue for 2024-25 (club accounts state GBP 173.1m turnover, record, with operating loss before player trading of GBP 40.0m and player-trading profit of GBP 27.2m). Debt: GBP 100m Macquarie facility from July 2025 is reported by analysts of the 2024/25 accounts (The Esk, Swiss Ramble), not by a club press release found here. The holding company BIA also owns Spanish club Merida AD. Benham''s original takeover was June 2012 (before the 2015 window). Social total is null because no source states a cross-platform total; per-platform counts are as displayed on the pages on 2026-09-28.', '["https://www.brentfordfc.com/en/news/article/club-news-brentford-new-investment-gary-lubner-sir-matthew-vaughn", "https://www.brentfordfc.com/en/news/club-news-brentford-announces-further-investment-prakash-melwani-sir-lucian-grainge-cbe", "https://www.sportspro.com/news/brentford-investment-gary-lubner-matthew-vaughn-benham-july-2025/", "https://www.insideworldfootball.com/2025/07/16/lubner-vaughn-take-minority-stakes-brentford/", "https://www.bloomberg.com/news/articles/2026-03-02/brentford-fc-gets-investment-from-music-mogul-blackstone-exec", "https://www.proskauer.com/release/proskauer-represents-prakash-melwani-in-minority-investment-in-best-intentions-analytics-limited-holding-company-of-brentford-fc-and-mrida-ad", "https://www.brentfordfc.com/en/news/article/club-news-brentford-fc-financial-results-2024-25", "https://www.brentfordfc.com/en/news/article/club-news-brentford-financial-results-announced-30-06-2023", "https://theesk.org/2026/05/12/the-analysis-series-financial-analysis-of-brentford-football-club-consolidation-capital-restructuring-and-the-2024-25-fiscal-cycle/", "https://swissramble.substack.com/p/brentford-finances-202425", "https://football-finance-files.beehiiv.com/p/deloitte-s-football-money-league-trends-2026", "https://www.sportico.com/valuations/teams/2026/most-valuable-soccer-teams-2026-real-madrid-barcelona-1234890790/", "https://www.forbes.com/sites/justinteitelbaum/2026/05/29/the-worlds-most-valuable-soccer-teams-2026/", "https://www.football-stadiums.co.uk/grounds/brentford-community-stadium/", "https://www.instagram.com/brentfordfc/", "https://www.facebook.com/brentfordfootballclub1889/", "https://www.speakrj.com/audit/report/BrentfordFC/twitter", "https://brandsownedby.com/who-owns-brentford-fc/"]'::jsonb, '[]'::jsonb, 'web_research')
  on conflict (external_key) do update set name = excluded.name, short_name = excluded.short_name, sport = excluded.sport, league = excluded.league, country = excluded.country, city = excluded.city, stadium = excluded.stadium, stadium_capacity = excluded.stadium_capacity, stadium_capacity_source_url = excluded.stadium_capacity_source_url, founded_year = excluded.founded_year, domain = excluded.domain, ownership_type = excluded.ownership_type, ownership_summary = excluded.ownership_summary, ownership_source_url = excluded.ownership_source_url, revenue = excluded.revenue, revenue_currency = excluded.revenue_currency, revenue_season = excluded.revenue_season, revenue_source_name = excluded.revenue_source_name, revenue_source_url = excluded.revenue_source_url, valuation = excluded.valuation, valuation_currency = excluded.valuation_currency, valuation_year = excluded.valuation_year, valuation_source_name = excluded.valuation_source_name, valuation_source_url = excluded.valuation_source_url, social_followers = excluded.social_followers, social_as_of = excluded.social_as_of, social_source_url = excluded.social_source_url, social_platforms = excluded.social_platforms, notes = excluded.notes, sources = excluded.sources, verification = excluded.verification, source = excluded.source;

insert into public.sports_teams (external_key, name, short_name, sport, league, country, city, stadium, stadium_capacity, stadium_capacity_source_url, founded_year, domain, ownership_type, ownership_summary, ownership_source_url, revenue, revenue_currency, revenue_season, revenue_source_name, revenue_source_url, valuation, valuation_currency, valuation_year, valuation_source_name, valuation_source_url, social_followers, social_as_of, social_source_url, social_platforms, notes, sources, verification, source)
  values ('premier-league--brighton-hove-albion', 'Brighton & Hove Albion Football Club', 'Brighton', 'football', 'Premier League', 'England', 'Brighton and Hove', 'American Express Stadium (Amex Stadium, Falmer)', 31876, 'https://footballgroundguide.com/leagues/england/premier-league/amex-stadium-brighton-and-hove-albion.html', 1901, 'brightonandhovealbion.com', 'individual_family', 'Chairman Tony Bloom has been majority owner since 2009, when he took a 75% stake in return for an interest-free loan to fund the Amex Stadium; he has since funded the club through interest-free shareholder loans (balance £406.5m at June 2025). Deputy chairman and CEO Paul Barber became the second largest shareholder with 1.5% via newly issued shares in August 2025.', 'https://www.brightonandhovealbion.com/media-article/club-news-paul-barber-investment-tony-bloom-august-2025', 222400000, 'GBP', '2024-25', 'Greg Cordell (club 2024/25 financial results)', 'https://gregcordell.substack.com/p/brighton-and-hove-albion-202425-financial', 910000000, 'USD', 2025, 'Forbes (via Wikipedia list of most valuable football clubs)', 'https://en.wikipedia.org/wiki/Forbes_list_of_the_most_valuable_football_clubs', null, '2026-09', 'https://www.brightonandhovealbion.com/club/fans/social-channels', '[{"platform": "Instagram", "followers": 2155380, "as_of": "2026-09", "source_url": "https://instastatistics.com/officialbhafc"}, {"platform": "Facebook", "followers": 2669274, "as_of": "2026-09", "source_url": "https://www.facebook.com/officialbhafc/"}, {"platform": "X", "followers": 1000000, "as_of": "2026-09", "source_url": "https://x.com/OfficialBHAFC?lang=en"}]'::jsonb, 'No private equity, sovereign or institutional capital in the club; funding is Tony Bloom''s interest-free shareholder loans (£406.5m owed at June 2025 per 2024-25 accounts; £109.8m had been repaid in 2022-23 and 2023-24 before £107m of new lending). Bloom''s 75% stake is the 2009 entry figure; a current precise percentage was not found in an authoritative source (one secondary site cites c.96.4% as of Nov 2025, unverified). Paul Barber holds 1.5% via newly issued shares (Aug 2025), consideration undisclosed. No takeover or stake-sale process reported. Valuation cross-references: Forbes 2025 $910m (rank 27); CNBC 2025 $920m (rank 24) and CNBC 2026 rank 29 with 2024-25 revenue $260m. Deloitte Money League 2026 lists Brighton 21st with EUR 256.8m revenue (2024-25); club accounts state GBP 222.4m for 2024-25, with a £55.8m loss. Bloom also holds stakes in Union Saint-Gilloise, Hearts (29%) and Melbourne Victory (19.1%), relevant to multi-club conversations.', '["https://www.brightonandhovealbion.com/media-article/club-news-paul-barber-investment-tony-bloom-august-2025", "https://www.brightonandhovenews.org/2025/08/29/barber-takes-stake-in-brighton-and-hove-albion/", "https://www.sussexexpress.co.uk/sport/football/brighton-and-hove-albion/revealed-the-staggering-amount-brighton-owner-tony-bloom-has-invested-in-albion-1334468", "https://en.wikipedia.org/wiki/Tony_Bloom", "https://gregcordell.substack.com/p/brighton-and-hove-albion-202425-financial", "https://www.wearebrighton.com/newsopinion/55-8m-loss-but-what-else-did-we-learn-from-brighton-2024-25-accounts/", "https://www.brightonandhovealbion.com/media-article/club-news-annual-accounts-published-2024-25-season-january-2026", "https://swissramble.substack.com/p/brighton-and-hove-albion-finances-28d", "https://www.footballbusinessinside.com/deloittes-2026-money-league-growth-at-the-top-pressure-below/", "https://en.wikipedia.org/wiki/Forbes_list_of_the_most_valuable_football_clubs", "https://www.forbes.com/teams/brighton-hove-albion/", "https://www.cnbc.com/2025/05/05/global-soccer-valuations-2025-brighton-and-hove-albion.html", "https://www.cnbc.com/2026/05/29/brighton-hove-albion-2026-cnbc-global-soccer-valuations.html", "https://instastatistics.com/officialbhafc", "https://www.facebook.com/officialbhafc/", "https://x.com/OfficialBHAFC?lang=en", "https://footballgroundguide.com/leagues/england/premier-league/amex-stadium-brighton-and-hove-albion.html", "https://www.brightonandhovealbion.com/mens-first-team-history"]'::jsonb, '[]'::jsonb, 'web_research')
  on conflict (external_key) do update set name = excluded.name, short_name = excluded.short_name, sport = excluded.sport, league = excluded.league, country = excluded.country, city = excluded.city, stadium = excluded.stadium, stadium_capacity = excluded.stadium_capacity, stadium_capacity_source_url = excluded.stadium_capacity_source_url, founded_year = excluded.founded_year, domain = excluded.domain, ownership_type = excluded.ownership_type, ownership_summary = excluded.ownership_summary, ownership_source_url = excluded.ownership_source_url, revenue = excluded.revenue, revenue_currency = excluded.revenue_currency, revenue_season = excluded.revenue_season, revenue_source_name = excluded.revenue_source_name, revenue_source_url = excluded.revenue_source_url, valuation = excluded.valuation, valuation_currency = excluded.valuation_currency, valuation_year = excluded.valuation_year, valuation_source_name = excluded.valuation_source_name, valuation_source_url = excluded.valuation_source_url, social_followers = excluded.social_followers, social_as_of = excluded.social_as_of, social_source_url = excluded.social_source_url, social_platforms = excluded.social_platforms, notes = excluded.notes, sources = excluded.sources, verification = excluded.verification, source = excluded.source;

insert into public.sports_teams (external_key, name, short_name, sport, league, country, city, stadium, stadium_capacity, stadium_capacity_source_url, founded_year, domain, ownership_type, ownership_summary, ownership_source_url, revenue, revenue_currency, revenue_season, revenue_source_name, revenue_source_url, valuation, valuation_currency, valuation_year, valuation_source_name, valuation_source_url, social_followers, social_as_of, social_source_url, social_platforms, notes, sources, verification, source)
  values ('premier-league--burnley', 'Burnley Football Club', 'Burnley', 'football', 'Premier League', 'England', 'Burnley', 'Turf Moor', 21944, 'https://en.wikipedia.org/wiki/Turf_Moor', 1882, 'burnleyfootballclub.com', 'private_equity', 'Controlled since December 2020 by Velocity Sports Partners, the sports investment arm of US firm ALK Capital (wholly owned by Alan Pace, Mike Smith and Stuart Hunt), which holds 84% of the club; the remaining 16% sits with individual minority shareholders including JJ and Kealia Watt and Malcolm Jenkins. In November 2025 ALK Capital took upwards of $200m from private equity fund Cynosure | Checketts Sports Capital.', 'https://alkcapital.com/2023/09/alk-capital-completes-investment-in-burnley-fc/', 71700000, 'GBP', '2024-25', 'The Swiss Ramble (Burnley FC Holdings Limited accounts 2024/25)', 'https://swissramble.substack.com/p/burnley-finances-202425', null, null, null, null, null, null, '2026-09-28', 'https://linktr.ee/burnleyfc', '[{"platform": "Instagram", "followers": 844000, "as_of": "2026-09-28", "source_url": "https://www.instagram.com/burnleyofficial/"}, {"platform": "X", "followers": 861700, "as_of": "2026-09-28", "source_url": "https://x.com/BurnleyOfficial"}, {"platform": "TikTok", "followers": 1200000, "as_of": "2026-09-28", "source_url": "https://www.tiktok.com/@burnleyofficial?lang=en"}, {"platform": "Facebook", "followers": 1204553, "as_of": "2026-09-28", "source_url": "https://www.facebook.com/burnleyofficial/"}]'::jsonb, 'Takeover price is disputed: Sportico and Fortune report about £170m; GiveMeSport reports £150m. Valuation left null because no Forbes or Sportico page in the results states a Burnley figure; GiveMeSport''s 2025-26 ranking puts Burnley at £200-220m (lowest in the Premier League) citing a blend of Forbes/Sportico/Football Benchmark estimates. Burnley is not in the Deloitte Money League top 20; revenue is from the club''s own 2024/25 accounts (Championship season, £71.7m, £28.5m post-tax loss). Accounts show bank borrowings of £105.3m at 7.25-12% secured on Turf Moor and group assets, with £40m reclassified as long-term after a post-year-end renegotiation; theesk.org flags a going-concern note. The Cynosure | Checketts $200m is at the ALK Capital parent level, not a direct club stake, and Bloomberg framed it as a stake sale bringing a new US investor into the Premier League. ALK also bought 99.66% of RCD Espanyol in October 2025 for a reported €130m, so Burnley is now part of a multi-club group. Social total is not stated by any single source, so the per-platform counts are listed separately.', '["https://alkcapital.com/2023/09/alk-capital-completes-investment-in-burnley-fc/", "https://burnleyfootballclub.com/legal-information/legal-information-company-details", "https://www.premierleague.com/en/news/1961150", "https://www.sportico.com/business/sales/2021/alk-capital-burnley-debt-1234621513/", "https://www.fortune.com/2021/02/06/burnley-alk-capital-private-equity-premier-league-leveraged-buyout", "https://frontofficesports.com/jj-watt-kealia-watt-invest-in-burnley-fc-english-premier-league/", "https://www.neworleanssaints.com/news/new-orleans-saints-safety-malcolm-jenkins-becomes-minority-investor-in-burnley-f", "https://alkcapital.com/2025/11/alk-capital-and-cynosure-checketts-sports-capital-reunite-in-significant-strategic-investment-across-european-football/", "https://www.bloomberg.com/news/articles/2025-11-03/premier-league-gets-new-us-investor-after-burnley-fc-stake-sale", "https://www.sportspro.com/news/espanyol-takeover-alk-capital-velocity-sport-burnley-laliga-july-2025/", "https://swissramble.substack.com/p/burnley-finances-202425", "https://theesk.org/2026/05/07/the-analysis-series-burnley-fc-holdings-limited-annual-report-and-financial-statements-2024-25/", "https://www.burnleyfootballclub.com/club-accounts", "https://www.givemesport.com/premier-league-every-club-ranked-most-least-valuable/", "https://en.wikipedia.org/wiki/Turf_Moor", "https://en.wikipedia.org/wiki/Burnley_F.C.", "https://www.instagram.com/burnleyofficial/", "https://x.com/BurnleyOfficial", "https://www.tiktok.com/@burnleyofficial?lang=en", "https://www.facebook.com/burnleyofficial/", "https://linktr.ee/burnleyfc"]'::jsonb, '[]'::jsonb, 'web_research')
