insert into public.sports_teams (external_key, name, short_name, sport, league, country, city, stadium, stadium_capacity, stadium_capacity_source_url, founded_year, domain, ownership_type, ownership_summary, ownership_source_url, revenue, revenue_currency, revenue_season, revenue_source_name, revenue_source_url, valuation, valuation_currency, valuation_year, valuation_source_name, valuation_source_url, social_followers, social_as_of, social_source_url, social_platforms, notes, sources, verification, source)
  values ('premier-league--chelsea', 'Chelsea Football Club', 'Chelsea', 'football', 'Premier League', 'England', 'London', 'Stamford Bridge', 40044, 'https://en.wikipedia.org/wiki/Stamford_Bridge_(stadium)', 1905, 'chelseafc.com', 'private_equity', 'Chelsea is controlled by Clearlake Capital Group, which held 61.5% from the May 2022 takeover of Roman Abramovich''s club and in September 2026 bought out co-owners Todd Boehly and Mark Walter (about 12.8% each) for £950m, taking full control at a £5bn valuation including debt. Hansjörg Wyss remains a minority shareholder; the holding company is BlueCo.', 'https://www.chelseafc.com/en/news/article/chelsea-fc-announces-ownership-transition', 584000000, 'EUR', '2024-25', 'Deloitte Football Money League 2026 (via Goal.com)', 'https://www.goal.com/en-us/news/deloitte-football-money-league-2026/bltedf9c4b411ec7212', 4200000000, 'USD', 2026, 'Forbes', 'https://www.forbes.com/sites/justinteitelbaum/2026/05/29/the-worlds-most-valuable-soccer-teams-2026/', 152900000, '2025', 'https://www.dailyfutbol.com/rankings/most-followed-football-clubs/', '[{"platform": "Instagram", "followers": 42586645, "as_of": "2026-09-28", "source_url": "https://socialblade.com/instagram/user/chelseafc"}, {"platform": "Facebook", "followers": 56500000, "as_of": "2025", "source_url": "https://www.dailyfutbol.com/rankings/most-followed-football-clubs/"}, {"platform": "X", "followers": 26200000, "as_of": "2025", "source_url": "https://www.dailyfutbol.com/rankings/most-followed-football-clubs/"}]'::jsonb, 'Ownership changed on 16 Sep 2026: Clearlake bought out Boehly and Walter (£950m, £5bn valuation incl. debt) after a reported feud; post-deal split reported as Clearlake 86.5% / Wyss 13.5% (some outlets still quote Wyss at 12.83%). Club accounts (year to 30 June 2025) show revenue £490.9m and a Premier League record £262.4m pre-tax loss; Deloitte''s €584m for 2024-25 differs by currency and scope. Sportico valued the club at $3.57bn (2025) and $4bn (2026) versus Forbes'' $4.2bn (May 2026). The 2024 women''s-team sale to sister company BlueCo (£198.7m) is contested for UEFA purposes and its £200m fair value was reported as awaiting Premier League approval. Ares £500m is subordinated PIK debt at HoldCo level, not equity. Social totals vary by source (152.9m vs 146.3m).', '["https://www.chelseafc.com/en/news/article/chelsea-fc-announces-ownership-transition", "https://www.espn.com/soccer/story/_/id/49960706/chelsea-clarlake-capital-todd-boehly-mark-walter-ownership", "https://www.cnbc.com/2026/09/17/chelsea-mark-walter-bohely-clearlake-capital.html", "https://www.bloomberg.com/news/articles/2026-09-16/walter-boehly-sell-chelsea-fc-stakes-to-clearlake-for-950m-ft", "https://pitchbook.com/news/articles/clearlake-acquires-full-control-of-chelsea-fc-for-950m", "https://www.espn.com/soccer/story/_/id/37628834/todd-boehly-completes-chelsea-takeover-deal-worth-425bn", "https://clearlake.com/news/consortium-led-by-todd-boehly-and-clearlake-capital-completes-acquisition-of-chelsea-football-club/", "https://www.bloomberg.com/news/articles/2023-09-22/chelsea-raises-500-million-of-financing-from-us-investor-ares", "https://www.espn.com/soccer/story/_/id/44481589/chelsea-huge-profit-repositioning-women-team", "https://www.sportspro.com/news/chelsea-women-alexis-ohanian-wsl-investment-stake-may-2025/", "https://www.goal.com/en-us/news/deloitte-football-money-league-2026/bltedf9c4b411ec7212", "https://www.chelseafc.com/en/news/article/financial-results-for-2024-25", "https://www.forbes.com/sites/justinteitelbaum/2026/05/29/the-worlds-most-valuable-soccer-teams-2026/", "https://www.sportico.com/valuations/teams/2025/most-valuable-soccer-clubs-2025-real-madrid-mls-1234851509/", "https://www.dailyfutbol.com/rankings/most-followed-football-clubs/", "https://socialblade.com/instagram/user/chelseafc", "https://en.wikipedia.org/wiki/Stamford_Bridge_(stadium)", "https://en.wikipedia.org/wiki/Chelsea_F.C."]'::jsonb, '[]'::jsonb, 'web_research')
  on conflict (external_key) do update set name = excluded.name, short_name = excluded.short_name, sport = excluded.sport, league = excluded.league, country = excluded.country, city = excluded.city, stadium = excluded.stadium, stadium_capacity = excluded.stadium_capacity, stadium_capacity_source_url = excluded.stadium_capacity_source_url, founded_year = excluded.founded_year, domain = excluded.domain, ownership_type = excluded.ownership_type, ownership_summary = excluded.ownership_summary, ownership_source_url = excluded.ownership_source_url, revenue = excluded.revenue, revenue_currency = excluded.revenue_currency, revenue_season = excluded.revenue_season, revenue_source_name = excluded.revenue_source_name, revenue_source_url = excluded.revenue_source_url, valuation = excluded.valuation, valuation_currency = excluded.valuation_currency, valuation_year = excluded.valuation_year, valuation_source_name = excluded.valuation_source_name, valuation_source_url = excluded.valuation_source_url, social_followers = excluded.social_followers, social_as_of = excluded.social_as_of, social_source_url = excluded.social_source_url, social_platforms = excluded.social_platforms, notes = excluded.notes, sources = excluded.sources, verification = excluded.verification, source = excluded.source;

insert into public.sports_teams (external_key, name, short_name, sport, league, country, city, stadium, stadium_capacity, stadium_capacity_source_url, founded_year, domain, ownership_type, ownership_summary, ownership_source_url, revenue, revenue_currency, revenue_season, revenue_source_name, revenue_source_url, valuation, valuation_currency, valuation_year, valuation_source_name, valuation_source_url, social_followers, social_as_of, social_source_url, social_platforms, notes, sources, verification, source)
  values ('premier-league--crystal-palace', 'Crystal Palace Football Club', 'Crystal Palace', 'football', 'Premier League', 'England', 'London', 'Selhurst Park', 25194, 'https://stadiumdb.com/stadiums/eng/selhurst_park', 1905, 'cpfc.co.uk', 'consortium', 'Owned by a consortium of individuals: New York Jets owner Woody Johnson (43%, bought John Textor''s Eagle Football stake in 2025), Josh Harris and David Blitzer (18% each since 2015) and chairman Steve Parish (just over 10%). In June 2026 the FT reported the owners had appointed Raine Group to explore options including a full sale.', 'https://www.wearepalace.uk/club/owners/', 196600000, 'GBP', '2024-25', 'The Swiss Ramble', 'https://swissramble.substack.com/p/crystal-palace-finances-202425', 790000000, 'USD', 2025, 'Forbes (via SI)', 'https://www.si.com/soccer/every-premier-league-club-valuation-ranked', 6700000, null, 'https://www.givemesport.com/premier-league-clubs-followers-ranked/', '[{"platform": "Instagram", "followers": 2000000, "as_of": "2026-09-28", "source_url": "https://www.instagram.com/cpfc/"}]'::jsonb, 'Ownership under review: in June 2026 the FT (via Irish Times / Inside Croydon) reported the owners had appointed Raine Group to run a process that could include a full sale or a controlling stake, alongside stadium-financing options ahead of a second European season. Stake figures vary by source: Wikipedia''s 2025-26 season page lists Johnson 45% / Harris 10% / Blitzer 10% / Parish 10%, while wearepalace.uk and the FT-derived reports give Johnson 43%, Harris and Blitzer 18% each (30% combined per FT) and Parish 10% or slightly over; the latter set is used here. Textor''s stake is described as 43% or about 45% depending on source. Valuations diverge: Forbes 2025 $790m (ranked 29th); Sportico June 2025 $610m (50th globally); Forbes 2026 keeps Palace at 29th, reported by LondonWorld as around £595m including stadium debt (USD figure not found); the Johnson deal implied £550m. Revenue: club-record £196.6m in 2024-25 (Swiss Ramble; MatchdayFinance rounds to £197m) with operating costs of £239.1m, so the club made a loss. Palace is not in the Deloitte Money League top 20. A 2019 sale memo by Zenith Global Capital Partners marketed 75-90% of the club at a £210m valuation; no deal resulted. Harris and Blitzer invest personally (not via Apollo/Blackstone funds), so no PE fund is recorded as an institutional investor. Selhurst Park capacity is quoted between 25,194 and about 26,000 by different sources; the Main Stand rebuild (started January 2026, Goldman Sachs £125m loan) takes it above 34,000. Social total of 6.7m (givemesport) has no stated as-of date.', '["https://www.sportico.com/business/team-sales/2025/crystal-palace-sale-woody-johnson-1234857577/", "https://www.nfl.com/news/jets-owner-woody-johnson-buys-43-stake-in-english-soccer-club-crystal-palace", "https://www.forbes.com/sites/robertolsen-1/2025/06/23/new-york-jets-billionaire-co-owner-buys-stake-in-crystal-palace-fc/", "https://www.espn.com/soccer/story/_/id/45813769/jets-owner-johnson-completes-purchase-stake-crystal-palace", "https://swissramble.substack.com/p/crystal-palace-finances-202425", "https://www.matchdayfinance.com/post/crystal-palace-financial-results-2024-25", "https://www.si.com/soccer/every-premier-league-club-valuation-ranked", "https://www.forbes.com/teams/crystal-palace/", "https://www.forbes.com/sites/justinteitelbaum/2026/05/29/the-worlds-most-valuable-soccer-teams-2026/", "https://www.londonworld.com/sport/football/crystal-palace/crystal-palace-club-valuation-2025-5258734", "https://www.instagram.com/cpfc/", "https://www.givemesport.com/premier-league-clubs-followers-ranked/", "https://stadiumdb.com/stadiums/eng/selhurst_park", "https://en.wikipedia.org/wiki/Crystal_Palace_F.C.", "https://www.cpfc.co.uk/crystal-palace-main-stand-redevelopment/", "https://www.cityam.com/who-owns-crystal-palace-now-how-much-did-john-textor-josh-harris-and-david-blitzer-and-his-co-owners-pay/", "https://www.johntextor.org/premier-league-statement", "https://www.sportbusiness.com/news/crystal-palace-confirms-investment-deal-with-american-businessmen/", "https://www.jonesday.com/en/practices/experience/2015/12/david-blitzer-and-josh-harris-make-significant-investment-in-crystal-palace-football-club", "https://www.bloomberg.com/news/articles/2015-12-19/apollo-s-josh-harris-completes-purchase-of-crystal-palace-soccer", "https://www.wearepalace.uk/club/owners/", "https://www.irishtimes.com/business/2026/06/16/us-billionaire-owners-of-crystal-palace-explore-sale/", "https://insidecroydon.com/2026/06/16/ft-reports-palaces-us-billionaire-owners-look-to-sell-shares/", "https://www.sportspro.com/news/crystal-palace-news-sale-document-parish-harris-blitzer/", "https://stadiumdb.com/news/2025/12/england_multimillion_loan_clears_the_way_for_selhurst_park_project_to_begin_in_january", "https://footballgroundguide.com/news/crystal-palace-secure-125m-boost-as-long-awaited-selhurst-park-redevelopment-finally-moves-forward.html"]'::jsonb, '[]'::jsonb, 'web_research')
  on conflict (external_key) do update set name = excluded.name, short_name = excluded.short_name, sport = excluded.sport, league = excluded.league, country = excluded.country, city = excluded.city, stadium = excluded.stadium, stadium_capacity = excluded.stadium_capacity, stadium_capacity_source_url = excluded.stadium_capacity_source_url, founded_year = excluded.founded_year, domain = excluded.domain, ownership_type = excluded.ownership_type, ownership_summary = excluded.ownership_summary, ownership_source_url = excluded.ownership_source_url, revenue = excluded.revenue, revenue_currency = excluded.revenue_currency, revenue_season = excluded.revenue_season, revenue_source_name = excluded.revenue_source_name, revenue_source_url = excluded.revenue_source_url, valuation = excluded.valuation, valuation_currency = excluded.valuation_currency, valuation_year = excluded.valuation_year, valuation_source_name = excluded.valuation_source_name, valuation_source_url = excluded.valuation_source_url, social_followers = excluded.social_followers, social_as_of = excluded.social_as_of, social_source_url = excluded.social_source_url, social_platforms = excluded.social_platforms, notes = excluded.notes, sources = excluded.sources, verification = excluded.verification, source = excluded.source;

insert into public.sports_teams (external_key, name, short_name, sport, league, country, city, stadium, stadium_capacity, stadium_capacity_source_url, founded_year, domain, ownership_type, ownership_summary, ownership_source_url, revenue, revenue_currency, revenue_season, revenue_source_name, revenue_source_url, valuation, valuation_currency, valuation_year, valuation_source_name, valuation_source_url, social_followers, social_as_of, social_source_url, social_platforms, notes, sources, verification, source)
  values ('premier-league--everton', 'Everton Football Club', 'Everton', 'football', 'Premier League', 'England', 'Liverpool', 'Hill Dickinson Stadium', 52769, 'https://en.wikipedia.org/wiki/Hill_Dickinson_Stadium', 1878, 'evertonfc.com', 'corporate', 'The Friedkin Group (Texas, chaired by Dan Friedkin, also owner of AS Roma) completed its takeover of Everton on 19 December 2024, buying Farhad Moshiri''s majority holding in a deal reported at more than £400m and taking a 98.8% stake after converting shareholder loans into equity. Moshiri, who bought 49.9% in 2016 and built up to 94.1%, exited entirely.', 'https://www.espn.com/soccer/story/_/id/42952286/everton-get-us-owners-friedkin-group-takeover-completed', 196700000, 'GBP', '2024-25', 'Everton FC (2024/25 Annual Report and Accounts)', 'https://www.evertonfc.com/news/2026/march/31/everton-publishes-2024-25-/', 930000000, 'USD', 2026, 'Forbes', 'https://www.forbes.com/sites/justinteitelbaum/2026/05/29/the-worlds-most-valuable-soccer-teams-2026/', null, null, null, '[{"platform": "Instagram", "followers": 3000000, "as_of": "2026-09-28", "source_url": "https://www.instagram.com/everton/"}, {"platform": "TikTok", "followers": 5500000, "as_of": "2026-09-28", "source_url": "https://www.tiktok.com/@everton"}]'::jsonb, 'Stake figures differ by source: ESPN/Sky report The Friedkin Group at 98.8%; The Esk''s analysis of filings gives 97.2% after converting the £451m shareholder loan to equity. Takeover price is reported only as ''in excess of £400m''. Valuations: Forbes 2026 $930m (first time on the Forbes list); Sportico $825m (May 2025, via SportsPro commercial guide); CNBC 2026 ranks Everton 27th. Everton is outside the Deloitte Money League 2026 top 20. Revenue £196.7m is club-record turnover for 2024/25 (loss £8.6m); 2025/26 is the first season at the 52,769-capacity Hill Dickinson Stadium (ESPN cited 52,888 at the time of the refinancing). Stadium debt is now the £350m senior secured notes (30-40 year tenor); the prior high-cost Rights and Media Funding, 777/A-Cap and MSP loans have all been repaid. Social total across platforms not stated by any source; Instagram (3M) and TikTok (5.5M) are page counts as seen 2026-09-28.', '["https://www.espn.com/soccer/story/_/id/42952286/everton-get-us-owners-friedkin-group-takeover-completed", "https://www.skysports.com/football/news/11095/13275439/everton-takeover-the-friedkin-group-complete-deal-to-become-clubs-new-owners", "https://www.espn.com/soccer/story/_/id/41397704/friedkin-group-farhad-moshiri-agree-deal", "https://www.malaymail.com/news/sports/2024/12/20/friedkin-group-completes-everton-takeover-becomes-10th-english-top-flight-club-under-american-ownership/160519", "https://www.evertonfc.com/news/2026/march/31/everton-publishes-2024-25-/", "https://www.premierleague.com/en/news/4623567", "https://theesk.org/2026/03/31/the-analysis-series-financial-reconstruction-analysis-of-everton-football-clubs-2024-25-annual-report-and-accounts/", "https://www.deloitte.com/uk/en/services/consulting-financial/analysis/deloitte-football-money-league.html", "https://www.forbes.com/sites/justinteitelbaum/2026/05/29/the-worlds-most-valuable-soccer-teams-2026/", "https://www.forbes.com/teams/everton/", "https://www.sportspro.com/commercial-guide/premier-league/teams/everton/", "https://www.cnbc.com/2026/05/29/everton-2026-cnbc-global-soccer-valuations.html", "https://www.instagram.com/everton/", "https://www.tiktok.com/@everton", "https://en.wikipedia.org/wiki/Hill_Dickinson_Stadium", "https://en.wikipedia.org/wiki/Everton_F.C.", "https://frontofficesports.com/everton-owner-invests-135m-in-club-increases-stake/", "https://www.skysports.com/football/news/11671/11736100/farhad-moshiri-increases-everton-ownership-to-77-2-per-cent", "https://global.espn.com/football/story/_/id/38403548/everton-sold-us-private-equity-firm-777-partners-moshiri-premier-league", "https://malaymail.com/news/sports/2024/06/01/everton-takeover-by-us-private-equity-firm-falls-through/137613", "https://www.sportspro.com/finance-investment/investment/777-partners-everton-takeover-bbl-lawsuits-fraud-sports-investments-josh-wander/", "https://theesk.org/2024/03/30/moshiri-is-about-to-lose-control-of-everton-the-question-is-to-whom/", "https://www.toffeeweb.com/season/23-24/news/44969.html", "https://theesk.org/2025/01/09/details-of-the-friedkin-financial-restructuring-of-everton-emerge/", "https://www.bloomberg.com/news/articles/2025-01-07/jpmorgan-sounds-out-investors-for-everton-fc-stadium-financing", "https://www.espn.com/soccer/story/_/id/44134148/everton-secure-350-million-financing-deal-new-stadium", "https://www.insideworldfootball.com/2025/03/26/everton-refinance-350m-bramley-moore-dock-stadium-debt/", "https://www.everton.news/breaking-news-the-friedkin-group-inject-another-107m-into-everton/"]'::jsonb, '[]'::jsonb, 'web_research')
