  values ('deal:arsenal-football-club:kroenke-sports-entertainment-stan-kroenke:2018-08-07', '2018-08-07', 'August 2018', 'acquisition', 'sports', 'football', 'Arsenal Football Club', 'club', 'England', (select id from public.sports_teams where external_key = 'premier-league--arsenal'), null, 'Kroenke Sports & Entertainment (Stan Kroenke)', 'individual', (select id from public.companies where lower(name) = lower('Kroenke Sports & Entertainment (Stan Kroenke)') limit 1), (select id from public.sports_investors where lower(name) = lower('Kroenke Sports & Entertainment (Stan Kroenke)') limit 1), 'Alisher Usmanov (Red and White Securities) and minority shareholders', 30.04, 550000000, 'GBP', 1800000000, 'GBP', 'Kroenke buys Usmanov''s 30% stake for £550m, takes Arsenal private', 'KSE, already holding 67%, agreed to buy Red and White Securities'' 30.04% stake for over £550m, valuing Arsenal at £1.8bn, and passed the 90% threshold to compulsorily purchase remaining minority shares and de-list the club. Reuters reported the total buyout cost £602m, funded with £45m of Kroenke''s own money and a £557m Deutsche Bank loan.', 'Forbes', 'https://www.forbes.com/sites/mikeozanian/2018/08/07/kroenke-buying-usmanovs-arsenal-stake-in-2-2-billion-lbo/', 'web_research')
