  values ('deal:aston-villa-football-club:nswe-nassef-sawiris-and-wes-edens:2018-07-20', '2018-07-20', 'July 2018', 'acquisition', 'sports', 'football', 'Aston Villa Football Club', 'club', 'England', (select id from public.sports_teams where external_key = 'premier-league--aston-villa'), null, 'NSWE (Nassef Sawiris and Wes Edens)', 'consortium', (select id from public.companies where lower(name) = lower('NSWE (Nassef Sawiris and Wes Edens)') limit 1), (select id from public.sports_investors where lower(name) = lower('NSWE (Nassef Sawiris and Wes Edens)') limit 1), 'Tony Xia (Recon Group)', 55, 30000000, 'GBP', null, null, 'Sawiris and Edens buy 55% controlling stake in Aston Villa for about £30m', 'Egyptian billionaire Nassef Sawiris and Fortress co-founder Wes Edens, through NSWE, acquired a 55% stake in Championship club Aston Villa for about £30m ($39m). Previous owner Tony Xia stayed as co-chairman. The club had faced cash-flow problems and a potential HMRC winding-up order over an unpaid £4m tax bill.', 'Bloomberg', 'https://www.bloomberg.com/news/articles/2018-07-20/billionaire-sawiris-wes-edens-to-buy-aston-villa-club-stake', 'web_research')
