  values ('deal:aston-villa-football-club:nswe-nassef-sawiris-and-wes-edens:august-2019', null, 'August 2019', 'acquisition', 'sports', 'football', 'Aston Villa Football Club', 'club', 'England', (select id from public.sports_teams where external_key = 'premier-league--aston-villa'), null, 'NSWE (Nassef Sawiris and Wes Edens)', 'consortium', (select id from public.companies where lower(name) = lower('NSWE (Nassef Sawiris and Wes Edens)') limit 1), (select id from public.sports_investors where lower(name) = lower('NSWE (Nassef Sawiris and Wes Edens)') limit 1), 'Tony Xia (Recon Group)', 45, null, null, null, null, 'Sawiris and Edens buy out Tony Xia''s remaining shares to own 100% of Aston Villa', 'Following promotion to the Premier League, NSWE increased its 55% holding to a full purchase of the club in August 2019, buying out Tony Xia''s remaining stake. Terms were not disclosed in the sources found.', 'Wikipedia (V Sports)', 'https://en.wikipedia.org/wiki/V_Sports', 'web_research')
