  values ('deal:aston-villa-football-club:atairos:2023-12-15', '2023-12-15', 'December 2023 (closed 12 April 2024)', 'minority_investment', 'sports', 'football', 'Aston Villa Football Club', 'club', 'England', (select id from public.sports_teams where external_key = 'premier-league--aston-villa'), null, 'Atairos', 'private_equity', (select id from public.companies where lower(name) = lower('Atairos') limit 1), (select id from public.sports_investors where lower(name) = lower('Atairos') limit 1), 'V Sports (Nassef Sawiris and Wes Edens)', 20, null, null, 500000000, 'GBP', 'Atairos takes 20% of V Sports at a valuation above £500m', 'V Sports, the holding company of Aston Villa, agreed a minority investment from Comcast-backed Atairos valuing V Sports at more than £500m. Atairos obtained a 20% stake in the holding company; V Sports continued to own 100% of AVFC and retain full control of club decisions. The deal was finalised on 12 April 2024.', 'Aston Villa FC (official)', 'https://www.avfc.co.uk/news/2023/december/15/v-sports-announces-investment-from-atairos/', 'web_research')
