  values ('deal:aston-villa-football-club:v-sports:2025-06-30', '2025-06-30', '30 June 2025', 'stake_sale', 'sports', 'football', 'Aston Villa Football Club', 'club', 'England', (select id from public.sports_teams where external_key = 'premier-league--aston-villa'), null, 'V Sports', 'corporate', (select id from public.companies where lower(name) = lower('V Sports') limit 1), (select id from public.sports_investors where lower(name) = lower('V Sports') limit 1), 'Aston Villa Football Club', 90, 55000000, 'GBP', 55000000, 'GBP', 'Aston Villa sells women''s team to parent V Sports at about £55m ahead of PSR deadline', 'Aston Villa agreed to sell Aston Villa Women to its own parent company V Sports for around £55m on 30 June 2025, with a 90% stake going to V Sports and 10% earmarked for an external US investor. The sale followed concern over a PSR breach after operating losses of around £195m across 2022-23 and 2023-24.', 'Insider Sport', 'https://insidersport.com/2025/07/03/aston-villa-psr-football-sale-women/', 'web_research')
