  values ('deal:brentford-football-club:gary-lubner-this-day-sports-and-media-ltd-and-sir-matthew-vaughn-marv-bee-ltd:2025-07-16', '2025-07-16', 'July 2025', 'minority_investment', 'sports', 'football', 'Brentford Football Club', 'club', 'England', (select id from public.sports_teams where external_key = 'premier-league--brentford'), null, 'Gary Lubner (This Day Sports and Media Ltd) and Sir Matthew Vaughn (MARV Bee Ltd)', 'individual', (select id from public.companies where lower(name) = lower('Gary Lubner (This Day Sports and Media Ltd) and Sir Matthew Vaughn (MARV Bee Ltd)') limit 1), (select id from public.sports_investors where lower(name) = lower('Gary Lubner (This Day Sports and Media Ltd) and Sir Matthew Vaughn (MARV Bee Ltd)') limit 1), 'Matthew Benham', null, null, null, 400000000, 'GBP', 'Lubner and Vaughn take minority stakes in Brentford at c.£400m valuation', 'Former Belron CEO Gary Lubner and filmmaker Sir Matthew Vaughn became minority shareholders in Best Intentions Analytics, the holding company for Brentford FC. Stake size was not disclosed; reports said up to 25% could ultimately change hands. Benham remains majority shareholder; board appointments subject to Premier League approval.', 'SportsPro', 'https://www.sportspro.com/news/brentford-investment-gary-lubner-matthew-vaughn-benham-july-2025/', 'web_research')
